// Dates that we need.
const now = cal.dtz.jsDateToDateTime(new Date()).getInTimezone(cal.dtz.UTC);
// For the first 60s after midninght, CalMetronome may not yet have updated minimonth.
const closeToRealMidnight =
  (now.hour == 23 && now.minute > 55) || (now.hour == 0 && now.minute == 0);
now.isDate = true;
const today = {
  year: now.year,
  month: now.month,
  day: now.day,
  weekday: now.weekday,
  weekdayName: cal.dtz.formatter.weekdayNames[now.weekday],
  shortWeekdayName: cal.dtz.formatter.shortWeekdayNames[now.weekday],
  calDate: now.clone(),
};
now.day--;
const yesterday = {
  year: now.year,
  month: now.month,
  day: now.day,
  weekday: now.weekday,
  weekdayName: cal.dtz.formatter.weekdayNames[now.weekday],
  shortWeekdayName: cal.dtz.formatter.shortWeekdayNames[now.weekday],
  jsDate: cal.dtz.dateTimeToJsDate(now),
  calDate: now.clone(),
};
now.day--;
const dayBeforeYesterday = {
  year: now.year,
  month: now.month,
  day: now.day,
  weekday: now.weekday,
  weekdayName: cal.dtz.formatter.weekdayNames[now.weekday],
  shortWeekdayName: cal.dtz.formatter.shortWeekdayNames[now.weekday],
  jsDate: cal.dtz.dateTimeToJsDate(now),
  calDate: now.clone(),
};

add_setup(async function () {
  Assert.equal(
    new Date().getDate(), // eslint-disable-line no-restricted-properties
    today.day,
    "This test will fail, because the local date and UTC date are not the same. You should be running this test in UTC."
  );
